create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,phase text not null default 'Recomp' check(phase in('Cut','Bulking','Recomp','ContestPrep')),target_calories numeric not null default 2400 check(target_calories>=0),target_protein_g numeric not null default 180 check(target_protein_g>=0),target_carbs_g numeric not null default 240 check(target_carbs_g>=0),target_fats_g numeric not null default 80 check(target_fats_g>=0),api_vault jsonb not null default '{}'::jsonb);
create table public.food_logs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),meal_category text not null check(meal_category in('Breakfast','Lunch','Dinner','Snack','IntraWorkout')),food_name text not null check(length(food_name) between 1 and 200),calories numeric not null default 0 check(calories>=0),protein_g numeric not null default 0 check(protein_g>=0),carbs_g numeric not null default 0 check(carbs_g>=0),fats_g numeric not null default 0 check(fats_g>=0),fiber_g numeric default 0,sugar_g numeric default 0,sodium_mg numeric default 0,potassium_mg numeric default 0,magnesium_mg numeric default 0,calcium_mg numeric default 0,iron_mg numeric default 0,zinc_mg numeric default 0,vitamin_a_rae_mcg numeric default 0,vitamin_c_mg numeric default 0,vitamin_d_iu numeric default 0,vitamin_e_mg numeric default 0,vitamin_k_mcg numeric default 0,vitamin_b1_mg numeric default 0,vitamin_b2_mg numeric default 0,vitamin_b3_mg numeric default 0,vitamin_b5_mg numeric default 0,vitamin_b6_mg numeric default 0,vitamin_b7_mcg numeric default 0,vitamin_b9_mcg numeric default 0,vitamin_b12_mcg numeric default 0,cholesterol_mg numeric default 0,saturated_fat_g numeric default 0,image_url text);
create table public.scale_logs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),raw_weight_lbs numeric not null check(raw_weight_lbs between 50 and 1000),moving_avg_lbs numeric,body_fat_pct numeric check(body_fat_pct between 0 and 100),hydration_pct numeric check(hydration_pct between 0 and 100));
create table public.coach_chats(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),role text not null check(role in('user','assistant')),content text not null check(length(content) between 1 and 20000));
create index food_logs_user_date on public.food_logs(user_id,created_at desc);
create index scale_logs_user_date on public.scale_logs(user_id,created_at desc);
create index coach_chats_user_date on public.coach_chats(user_id,created_at desc);
alter table public.profiles enable row level security;
alter table public.food_logs enable row level security;
alter table public.scale_logs enable row level security;
alter table public.coach_chats enable row level security;
create policy profiles_select on public.profiles for select to authenticated using(auth.uid()=id);
create policy profiles_insert on public.profiles for insert to authenticated with check(auth.uid()=id);
create policy profiles_update on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
create policy profiles_delete on public.profiles for delete to authenticated using(auth.uid()=id);
create policy food_select on public.food_logs for select to authenticated using(auth.uid()=user_id);
create policy food_insert on public.food_logs for insert to authenticated with check(auth.uid()=user_id);
create policy food_update on public.food_logs for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy food_delete on public.food_logs for delete to authenticated using(auth.uid()=user_id);
create policy scale_select on public.scale_logs for select to authenticated using(auth.uid()=user_id);
create policy scale_insert on public.scale_logs for insert to authenticated with check(auth.uid()=user_id);
create policy scale_update on public.scale_logs for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy scale_delete on public.scale_logs for delete to authenticated using(auth.uid()=user_id);
create policy chats_select on public.coach_chats for select to authenticated using(auth.uid()=user_id);
create policy chats_insert on public.coach_chats for insert to authenticated with check(auth.uid()=user_id);
create policy chats_update on public.coach_chats for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy chats_delete on public.coach_chats for delete to authenticated using(auth.uid()=user_id);
create function public.new_user_profile() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id) values(new.id);return new;end$$;
create trigger auth_profile after insert on auth.users for each row execute function public.new_user_profile();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('food-images','food-images',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy image_read on storage.objects for select to authenticated using(bucket_id='food-images' and (storage.foldername(name))[1]=auth.uid()::text);
create policy image_insert on storage.objects for insert to authenticated with check(bucket_id='food-images' and (storage.foldername(name))[1]=auth.uid()::text);
create policy image_delete on storage.objects for delete to authenticated using(bucket_id='food-images' and (storage.foldername(name))[1]=auth.uid()::text);
